#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Public contract version 1.1.1, request schema version 1.

Reads JSON Lines on stdin, writes one JSON response per line on stdout.
Diagnostics go to stderr.
"""
import json
import re
import sys
import traceback
from fractions import Fraction
from math import lcm

import z3

# --------------------------------------------------------------------------
# Schema validation
# --------------------------------------------------------------------------

_NAME_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
_METRICS = ('demand', 'link', 'ingress', 'egress')


class Invalid(Exception):
    """Raised for any schema violation."""


def _bad_const(_):
    raise ValueError('nonstandard constant')


def is_name(v):
    return type(v) is str and _NAME_RE.fullmatch(v) is not None


def need_int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        raise Invalid()
    return v


def need_list(v, lo, hi):
    if not isinstance(v, list) or not (lo <= len(v) <= hi):
        raise Invalid()
    return v


def unique_names(values):
    seen = set()
    for v in values:
        if not is_name(v):
            raise Invalid()
        if v in seen:
            raise Invalid()
        seen.add(v)
    return seen


def parse_request(req):
    if not isinstance(req, dict):
        raise Invalid()
    rid = req.get('id')
    if not is_name(rid):
        raise Invalid()
    need_int(req.get('version'), 1, 1)

    nodes = need_list(req.get('nodes'), 2, 12)
    node_set = unique_names(nodes)

    raw_edges = need_list(req.get('edges'), 0, 32)
    edges = []
    edge_ids = set()
    for e in raw_edges:
        if not isinstance(e, dict):
            raise Invalid()
        eid = e.get('id')
        if not is_name(eid) or eid in edge_ids:
            raise Invalid()
        edge_ids.add(eid)
        src = e.get('source')
        tgt = e.get('target')
        if not is_name(src) or src not in node_set:
            raise Invalid()
        if not is_name(tgt) or tgt not in node_set or tgt == src:
            raise Invalid()
        cap = need_int(e.get('capacity'), 0, 1000000)
        edges.append({'id': eid, 'source': src, 'target': tgt, 'capacity': cap})
    edge_index = {e['id']: i for i, e in enumerate(edges)}

    raw_coms = need_list(req.get('commodities'), 0, 12)
    commodities = []
    com_ids = set()
    com_pairs = set()
    for c in raw_coms:
        if not isinstance(c, dict):
            raise Invalid()
        cid = c.get('id')
        if not is_name(cid) or cid in com_ids:
            raise Invalid()
        com_ids.add(cid)
        src = c.get('source')
        tgt = c.get('target')
        if not is_name(src) or src not in node_set:
            raise Invalid()
        if not is_name(tgt) or tgt not in node_set or tgt == src:
            raise Invalid()
        if (src, tgt) in com_pairs:
            raise Invalid()
        com_pairs.add((src, tgt))
        raw_routes = need_list(c.get('routes'), 1, 3)
        routes = []
        weight_sum = 0
        for r in raw_routes:
            if not isinstance(r, dict):
                raise Invalid()
            w = need_int(r.get('weight'), 1, 8)
            weight_sum += w
            if weight_sum > 8:
                raise Invalid()
            relist = need_list(r.get('edges'), 1, 64)
            eids = []
            for x in relist:
                if not is_name(x) or x not in edge_index:
                    raise Invalid()
                eids.append(x)
            cur = src
            seen_nodes = {cur}
            for x in eids:
                ed = edges[edge_index[x]]
                if ed['source'] != cur:
                    raise Invalid()
                cur = ed['target']
                if cur in seen_nodes:
                    raise Invalid()
                seen_nodes.add(cur)
            if cur != tgt:
                raise Invalid()
            routes.append({'edges': eids, 'weight': w})
        commodities.append({'id': cid, 'source': src, 'target': tgt,
                            'routes': routes})
    com_index = {c['id']: i for i, c in enumerate(commodities)}

    domains = need_list(req.get('domains'), 0, 14)
    domain_set = unique_names(domains)

    max_faults = need_int(req.get('max_faults'), 0, 14)
    if max_faults > len(domains):
        raise Invalid()

    raw_snaps = need_list(req.get('snapshots'), 1, 4)
    snapshots = []
    snap_ids = set()
    obs_total = 0
    for sp in raw_snaps:
        if not isinstance(sp, dict):
            raise Invalid()
        sid = sp.get('id')
        if not is_name(sid) or sid in snap_ids:
            raise Invalid()
        snap_ids.add(sid)
        raw_bounds = need_list(sp.get('bounds'), len(commodities),
                               len(commodities))
        bounds = []
        for b in raw_bounds:
            if not isinstance(b, list) or len(b) != 2:
                raise Invalid()
            lo = need_int(b[0], 0, 10000)
            hi = need_int(b[1], 0, 10000)
            if lo > hi:
                raise Invalid()
            bounds.append((lo, hi))
        raw_ctrl = need_list(sp.get('controller'), len(commodities),
                             len(commodities))
        controller = [need_int(v, 0, 10000) for v in raw_ctrl]
        tolerance = need_int(sp.get('tolerance'), 0, 10000)
        raw_obs = need_list(sp.get('observations'), 0, 96)
        obs_total += len(raw_obs)
        if obs_total > 256:
            raise Invalid()
        observations = []
        obs_ids = set()
        for o in raw_obs:
            if not isinstance(o, dict):
                raise Invalid()
            oid = o.get('id')
            if not is_name(oid) or oid in obs_ids:
                raise Invalid()
            obs_ids.add(oid)
            if 'domain' not in o:
                raise Invalid()
            metric = o.get('metric')
            if not isinstance(metric, str) or metric not in _METRICS:
                raise Invalid()
            target = o.get('target')
            if not is_name(target):
                raise Invalid()
            if metric == 'demand':
                if target not in com_index:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_index:
                    raise Invalid()
            else:
                if target not in node_set:
                    raise Invalid()
            lower = need_int(o.get('lower'), -1000000, 1000000)
            upper = need_int(o.get('upper'), -1000000, 1000000)
            if lower > upper:
                raise Invalid()
            dom = o['domain']
            if dom is not None and (not is_name(dom) or dom not in domain_set):
                raise Invalid()
            observations.append({'id': oid, 'metric': metric, 'target': target,
                                 'lower': lower, 'upper': upper, 'domain': dom})
        snapshots.append({'id': sid, 'bounds': bounds, 'controller': controller,
                          'tolerance': tolerance, 'observations': observations})

    return {'id': rid, 'nodes': nodes, 'edges': edges,
            'commodities': commodities, 'domains': domains,
            'max_faults': max_faults, 'snapshots': snapshots}


# --------------------------------------------------------------------------
# Model construction
# --------------------------------------------------------------------------

class Model(object):
    """Scaled integer model of one incident request."""

    def __init__(self, inst):
        self.inst = inst
        nodes = inst['nodes']
        edges = inst['edges']
        coms = inst['commodities']
        snaps = inst['snapshots']
        self.E = len(edges)
        self.C = len(coms)
        self.S = len(snaps)
        edge_index = {e['id']: i for i, e in enumerate(edges)}
        com_index = {c['id']: i for i, c in enumerate(coms)}
        node_index = {n: i for i, n in enumerate(nodes)}

        K = 1
        for c in coms:
            K = lcm(K, sum(r['weight'] for r in c['routes']))
        self.K = K

        n = [[0] * self.E for _ in range(self.C)]
        for ci, c in enumerate(coms):
            W = sum(r['weight'] for r in c['routes'])
            sc = K // W
            for r in c['routes']:
                w = r['weight'] * sc
                for eid in r['edges']:
                    n[ci][edge_index[eid]] += w
        self.n = n

        self.link_coef = [tuple(n[ci][ei] for ci in range(self.C))
                          for ei in range(self.E)]
        self.dem_coef = [tuple(K if ci == j else 0 for ci in range(self.C))
                         for j in range(self.C)]
        self.ing_coef = [tuple(K if coms[ci]['source'] == v else 0
                               for ci in range(self.C)) for v in nodes]
        self.egr_coef = [tuple(K if coms[ci]['target'] == v else 0
                               for ci in range(self.C)) for v in nodes]

        def coef_of(metric, target):
            if metric == 'demand':
                return self.dem_coef[com_index[target]]
            if metric == 'link':
                return self.link_coef[edge_index[target]]
            if metric == 'ingress':
                return self.ing_coef[node_index[target]]
            return self.egr_coef[node_index[target]]

        domains = inst['domains']
        self.dom_obs = {d: [] for d in domains}
        self.trusted = []
        for si, sp in enumerate(snaps):
            for o in sp['observations']:
                coef = coef_of(o['metric'], o['target'])
                lo = o['lower'] * K
                hi = o['upper'] * K
                if o['domain'] is None:
                    self.trusted.append((si, coef, lo, hi))
                else:
                    self.dom_obs[o['domain']].append((si, coef, lo, hi))
        self.observed_domains = [d for d in domains if self.dom_obs[d]]

    def build(self):
        C, S = self.C, self.S
        q = [[z3.Int('q_%d_%d' % (s, c)) for c in range(C)] for s in range(S)]
        self.q = q
        base = []
        snaps = self.inst['snapshots']
        for s in range(S):
            bnd = snaps[s]['bounds']
            for c in range(C):
                lo, hi = bnd[c]
                if lo > 0:
                    base.append(q[s][c] >= lo)
                base.append(q[s][c] <= hi)
        K = self.K
        for s in range(S):
            for ei in range(self.E):
                coef = self.link_coef[ei]
                cap = self.inst['edges'][ei]['capacity'] * K
                terms = [coef[c] * q[s][c] for c in range(C) if coef[c]]
                if not terms:
                    continue
                base.append(z3.Sum(terms) <= cap)
        self._exprs = {}
        for (si, coef, lo, hi) in self.trusted:
            e = self.expr(si, coef)
            base.append(e >= lo)
            base.append(e <= hi)
        self.fvars = {}
        for i, d in enumerate(self.observed_domains):
            fb = z3.Bool('f_%d' % i)
            self.fvars[d] = fb
            conj = []
            for (si, coef, lo, hi) in self.dom_obs[d]:
                e = self.expr(si, coef)
                conj.append(e >= lo)
                conj.append(e <= hi)
            base.append(z3.Implies(z3.Not(fb), z3.And(conj)))
        self.base = base
        return base

    def expr(self, s, coef):
        key = (s, coef)
        e = self._exprs.get(key)
        if e is None:
            terms = [coef[c] * self.q[s][c] for c in range(self.C) if coef[c]]
            e = z3.Sum(terms) if terms else z3.IntVal(0)
            self._exprs[key] = e
        return e


# --------------------------------------------------------------------------
# Solving
# --------------------------------------------------------------------------

def as_int_value(v):
    try:
        if z3.is_int_value(v):
            return v.as_long()
        if z3.is_rat_value(v):
            f = v.as_fraction()
            if f.denominator == 1:
                return f.numerator
        if z3.is_real_value(v):
            f = v.as_fraction()
            if f.denominator == 1:
                return f.numerator
    except Exception:
        return None
    return None


def solve(inst):
    rid = inst['id']
    mdl = Model(inst)
    mdl.build()
    C, S, E, K = mdl.C, mdl.S, mdl.E, mdl.K
    snaps = inst['snapshots']
    fvars = [mdl.fvars[d] for d in mdl.observed_domains]

    def dot(coef, values):
        return sum(cf * v for cf, v in zip(coef, values) if cf)

    def evaluate(wq_values):
        links = [[dot(mdl.link_coef[ei], wq_values[s]) for ei in range(E)]
                 for s in range(S)]
        faults = []
        for d in mdl.observed_domains:
            for (si, coef, lo, hi) in mdl.dom_obs[d]:
                v = dot(coef, wq_values[si])
                if v < lo or v > hi:
                    faults.append(d)
                    break
        return links, faults

    opt = z3.Optimize()
    opt.add(mdl.base)

    # ---- minimum number of faulty domains ------------------------------
    k = None
    for m in range(inst['max_faults'] + 1):
        opt.push()
        if fvars:
            opt.add(z3.AtMost(fvars, m))
        r = opt.check()
        opt.pop()
        if r == z3.sat:
            k = m
            break
        if r == z3.unknown:
            raise RuntimeError('z3 unknown while searching k')
    if k is None:
        return {'id': rid, 'status': 'infeasible'}
    if fvars:
        opt.add(z3.AtMost(fvars, k))
        opt.add(z3.AtLeast(fvars, k))

    # ---- exact extrema of linear objectives ----------------------------
    cache = {}

    def static_bounds(s, coef):
        lo = 0
        hi = 0
        for c in range(C):
            cf = coef[c]
            if cf == 0:
                continue
            blo, bhi = snaps[s]['bounds'][c]
            if cf > 0:
                lo += cf * blo
                hi += cf * bhi
            else:
                lo += cf * bhi
                hi += cf * blo
        return lo, hi

    def search_bound(s, coef, lo, hi, maximize):
        e = mdl.expr(s, coef)
        best = None
        while lo <= hi:
            mid = (lo + hi) // 2
            opt.push()
            if maximize:
                opt.add(e >= mid)
            else:
                opt.add(e <= mid)
            r = opt.check()
            opt.pop()
            if r == z3.sat:
                best = mid
                if maximize:
                    lo = mid + 1
                else:
                    hi = mid - 1
            elif r == z3.unsat:
                if maximize:
                    hi = mid - 1
                else:
                    lo = mid + 1
            else:
                break
        if best is None:
            best = hi if maximize else lo
        return best

    def optimum(s, coef, maximize):
        key = (s, coef, maximize)
        hit = cache.get(key)
        if hit is not None:
            return hit
        slo, shi = static_bounds(s, coef)
        if slo == shi:
            cache[key] = slo
            return slo
        val = None
        try:
            opt.push()
            e = mdl.expr(s, coef)
            h = opt.maximize(e) if maximize else opt.minimize(e)
            r = opt.check()
            if r == z3.sat:
                val = as_int_value(opt.upper(h) if maximize else opt.lower(h))
            elif r == z3.unknown:
                val = None
            opt.pop()
        except Exception:
            traceback.print_exc()
            try:
                opt.pop()
            except Exception:
                pass
            val = None
        if val is None:
            val = search_bound(s, coef, slo, shi, maximize)
        cache[key] = val
        return val

    # ---- demand and link ranges ----------------------------------------
    dem_ranges = []
    link_ranges = []
    ambiguous = False
    for s in range(S):
        row = []
        for c in range(C):
            blo, bhi = snaps[s]['bounds'][c]
            if blo == bhi:
                row.append([blo, bhi])
            else:
                coef = mdl.dem_coef[c]
                lo = optimum(s, coef, False) // K
                hi = optimum(s, coef, True) // K
                row.append([lo, hi])
                if lo != hi:
                    ambiguous = True
        dem_ranges.append(row)
        lrow = []
        for ei in range(E):
            coef = mdl.link_coef[ei]
            lo = optimum(s, coef, False)
            hi = optimum(s, coef, True)
            lrow.append([str(Fraction(lo, K)), str(Fraction(hi, K))])
        link_ranges.append(lrow)

    # ---- witness --------------------------------------------------------
    r = opt.check()
    if r != z3.sat:
        raise RuntimeError('no witness although k was found')
    m = opt.model()
    wq = [[m.evaluate(mdl.q[s][c], model_completion=True).as_long()
           for c in range(C)] for s in range(S)]
    wlinks, wfaults = evaluate(wq)
    if len(wfaults) != k:
        raise RuntimeError('witness fault count %d != k %d' % (len(wfaults), k))
    status = 'ambiguous' if ambiguous else 'unique'

    # ---- forced / possible fault domains --------------------------------
    forced = []
    possible = []
    for d in mdl.observed_domains:
        fb = mdl.fvars[d]
        opt.push()
        opt.add(z3.Not(fb))
        r1 = opt.check()
        opt.pop()
        if r1 == z3.unsat:
            forced.append(d)
            possible.append(d)
            continue
        if r1 == z3.unknown:
            raise RuntimeError('z3 unknown in fault query')
        opt.push()
        opt.add(fb)
        r2 = opt.check()
        opt.pop()
        if r2 == z3.sat:
            possible.append(d)
        elif r2 == z3.unknown:
            raise RuntimeError('z3 unknown in fault query')

    # ---- controller verdicts --------------------------------------------
    verdicts = []
    for s in range(S):
        ctrl = snaps[s]['controller']
        tol = snaps[s]['tolerance']
        agree = []
        for c in range(C):
            agree.append(mdl.q[s][c] >= ctrl[c] - tol)
            agree.append(mdl.q[s][c] <= ctrl[c] + tol)
        a = z3.And(agree) if agree else z3.BoolVal(True)
        opt.push()
        opt.add(a)
        r_yes = opt.check()
        opt.pop()
        opt.push()
        opt.add(z3.Not(a))
        r_no = opt.check()
        opt.pop()
        if r_yes == z3.unknown or r_no == z3.unknown:
            raise RuntimeError('z3 unknown in verdict query')
        if r_yes == z3.sat and r_no == z3.sat:
            verdicts.append('undetermined')
        elif r_yes == z3.sat:
            verdicts.append('consistent')
        else:
            verdicts.append('inconsistent')

    # ---- alternative witness --------------------------------------------
    alt = None
    if ambiguous:
        for s in range(S):
            if alt is not None:
                break
            for c in range(C):
                lo, hi = dem_ranges[s][c]
                if lo == hi:
                    continue
                v = wq[s][c]
                extra = (mdl.q[s][c] >= v + 1) if v < hi else (mdl.q[s][c] <= v - 1)
                opt.push()
                opt.add(extra)
                rr = opt.check()
                if rr == z3.sat:
                    m2 = opt.model()
                    aq = [[m2.evaluate(mdl.q[ss][cc], model_completion=True).as_long()
                           for cc in range(C)] for ss in range(S)]
                    alinks, afaults = evaluate(aq)
                    alt = {'demands': aq, 'links': [[str(Fraction(v2, K)) for v2 in row]
                                                    for row in alinks],
                           'faults': afaults}
                elif rr == z3.unknown:
                    opt.pop()
                    raise RuntimeError('z3 unknown in alternative query')
                opt.pop()
                if alt is not None:
                    break
        if alt is None:
            raise RuntimeError('ambiguous but no alternative found')

    snap_out = [{'id': snaps[s]['id'], 'demands': dem_ranges[s],
                 'links': link_ranges[s], 'verdict': verdicts[s]}
                for s in range(S)]

    return {'id': rid, 'status': status, 'min_faults': k,
            'faults': {'forced': forced, 'possible': possible},
            'snapshots': snap_out,
            'witness': {'demands': wq,
                        'links': [[str(Fraction(v, K)) for v in row]
                                  for row in wlinks],
                        'faults': wfaults},
            'alternative': alt}


# --------------------------------------------------------------------------
# Driver
# --------------------------------------------------------------------------

def process_line(raw):
    try:
        value = json.loads(raw, parse_constant=_bad_const)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if isinstance(value, dict):
        cand = value.get('id')
        if is_name(cand):
            rid = cand
    try:
        inst = parse_request(value)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except RecursionError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        return solve(inst)
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    out = sys.stdout
    for raw in lines:
        out.write(json.dumps(process_line(raw), separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
