            except Exception as e:
                errs.append(('witness-exc', repr(e), ''))
        if errs:
            bad += 1
            print('MISMATCH', json.dumps(inst_raw))
            print(' exp', json.dumps(exp)[:800])
            print(' act', json.dumps(act)[:800])
            print(' errs', errs)
            if bad > 4:
                break
    print('done %d cases, %d bad, %.1fs, stats=%s, slowest=%.2fs' %
          (n, bad, time.time() - t0, stats, slowest[0]))

main()
