#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer.

Public contract version 1.1.1, request schema version 1.

Reads JSON Lines on stdin, writes exactly one JSON response per input line on
stdout.  Diagnostics go to stderr.

Method
------
Let q[s][c] be the integer demand of commodity c in snapshot s.  Every derived
quantity (edge load, ingress/egress totals) is a rational linear function of q,
so all constraints are linear after scaling by K = lcm(route weight sums).

A domain d is faulty exactly when one of its observations is violated, hence
the set of faulty domains is a function of q.  Introducing one boolean f_d per
*observed* domain with the implication

    (all observations of d hold)  <=  (not f_d)

together with the cardinality constraint sum_d f_d = k gives an encoding whose
models are exactly the optimal explanations F:  any q obeying bounds, capacity
and trusted observations violates at least k domains (k is minimal), so a model
with sum f_d = k has exactly k violated domains and f_d is that indicator.

Ranges over F are obtained as exact extrema of linear objectives.  For each
objective a rational (real-valued) relaxation of the same model supplies tight
bounds, and the exact integer extremum is then recovered with a handful of
incremental satisfiability checks (binary search).  Both bounds are attained.
"""
import json
import os
import re
import sys
import time
import traceback
from fractions import Fraction
from math import lcm

import z3

# --------------------------------------------------------------------------
# Schema validation
# --------------------------------------------------------------------------

_NAME_RE = re.compile(r'[A-Za-z][A-Za-z0-9_-]{0,31}')
_METRICS = ('demand', 'link', 'ingress', 'egress')


class Invalid(Exception):
    """Raised for any schema violation."""


class EngineError(Exception):
    """Raised when the inference engine cannot produce an exact answer."""


def _bad_const(_):
    raise ValueError('nonstandard constant')


def is_name(v):
    return type(v) is str and _NAME_RE.fullmatch(v) is not None


def need_int(v, lo, hi):
    if type(v) is not int or v < lo or v > hi:
        raise Invalid()
    return v


def need_list(v, lo, hi):
    if not isinstance(v, list) or not (lo <= len(v) <= hi):
        raise Invalid()
    return v


def unique_names(values):
    seen = set()
    for v in values:
        if not is_name(v):
            raise Invalid()
        if v in seen:
            raise Invalid()
        seen.add(v)
    return seen


def parse_request(req):
    """Validate one decoded request; return a plain dict or raise Invalid."""
    if not isinstance(req, dict):
        raise Invalid()
    rid = req.get('id')
    if not is_name(rid):
        raise Invalid()
    need_int(req.get('version'), 1, 1)

    nodes = need_list(req.get('nodes'), 2, 12)
    node_set = unique_names(nodes)

    raw_edges = need_list(req.get('edges'), 0, 32)
    edges = []
    edge_ids = set()
    for e in raw_edges:
        if not isinstance(e, dict):
            raise Invalid()
        eid = e.get('id')
        if not is_name(eid) or eid in edge_ids:
            raise Invalid()
        edge_ids.add(eid)
        src = e.get('source')
        tgt = e.get('target')
        if not is_name(src) or src not in node_set:
            raise Invalid()
        if not is_name(tgt) or tgt not in node_set or tgt == src:
            raise Invalid()
        cap = need_int(e.get('capacity'), 0, 1000000)
        edges.append({'id': eid, 'source': src, 'target': tgt, 'capacity': cap})
    edge_index = {e['id']: i for i, e in enumerate(edges)}

    raw_coms = need_list(req.get('commodities'), 0, 12)
    commodities = []
    com_ids = set()
    com_pairs = set()
    for c in raw_coms:
        if not isinstance(c, dict):
            raise Invalid()
        cid = c.get('id')
        if not is_name(cid) or cid in com_ids:
            raise Invalid()
        com_ids.add(cid)
        src = c.get('source')
        tgt = c.get('target')
        if not is_name(src) or src not in node_set:
            raise Invalid()
        if not is_name(tgt) or tgt not in node_set or tgt == src:
            raise Invalid()
        if (src, tgt) in com_pairs:
            raise Invalid()
        com_pairs.add((src, tgt))
        raw_routes = need_list(c.get('routes'), 1, 3)
        routes = []
        weight_sum = 0
        for r in raw_routes:
            if not isinstance(r, dict):
                raise Invalid()
            w = need_int(r.get('weight'), 1, 8)
            weight_sum += w
            if weight_sum > 8:
                raise Invalid()
            relist = need_list(r.get('edges'), 1, 64)
            eids = []
            for x in relist:
                if not is_name(x) or x not in edge_index:
                    raise Invalid()
                eids.append(x)
            cur = src
            seen_nodes = {cur}
            for x in eids:
                ed = edges[edge_index[x]]
                if ed['source'] != cur:
                    raise Invalid()
                cur = ed['target']
                if cur in seen_nodes:
                    raise Invalid()
                seen_nodes.add(cur)
            if cur != tgt:
                raise Invalid()
            routes.append({'edges': eids, 'weight': w})
        commodities.append({'id': cid, 'source': src, 'target': tgt,
                            'routes': routes})
    com_index = {c['id']: i for i, c in enumerate(commodities)}

    domains = need_list(req.get('domains'), 0, 14)
    domain_set = unique_names(domains)

    max_faults = need_int(req.get('max_faults'), 0, 14)
    if max_faults > len(domains):
        raise Invalid()

    raw_snaps = need_list(req.get('snapshots'), 1, 4)
    snapshots = []
    snap_ids = set()
    obs_total = 0
    for sp in raw_snaps:
        if not isinstance(sp, dict):
            raise Invalid()
        sid = sp.get('id')
        if not is_name(sid) or sid in snap_ids:
            raise Invalid()
        snap_ids.add(sid)
        raw_bounds = need_list(sp.get('bounds'), len(commodities),
                               len(commodities))
        bounds = []
        for b in raw_bounds:
            if not isinstance(b, list) or len(b) != 2:
                raise Invalid()
            lo = need_int(b[0], 0, 10000)
            hi = need_int(b[1], 0, 10000)
            if lo > hi:
                raise Invalid()
            bounds.append((lo, hi))
        raw_ctrl = need_list(sp.get('controller'), len(commodities),
                             len(commodities))
        controller = [need_int(v, 0, 10000) for v in raw_ctrl]
        tolerance = need_int(sp.get('tolerance'), 0, 10000)
        raw_obs = need_list(sp.get('observations'), 0, 96)
        obs_total += len(raw_obs)
        if obs_total > 256:
            raise Invalid()
        observations = []
        obs_ids = set()
        for o in raw_obs:
            if not isinstance(o, dict):
                raise Invalid()
            oid = o.get('id')
            if not is_name(oid) or oid in obs_ids:
                raise Invalid()
            obs_ids.add(oid)
            if 'domain' not in o:
                raise Invalid()
            metric = o.get('metric')
            if not isinstance(metric, str) or metric not in _METRICS:
                raise Invalid()
            target = o.get('target')
            if not is_name(target):
                raise Invalid()
            if metric == 'demand':
                if target not in com_index:
                    raise Invalid()
            elif metric == 'link':
                if target not in edge_index:
                    raise Invalid()
            else:
                if target not in node_set:
                    raise Invalid()
            lower = need_int(o.get('lower'), -1000000, 1000000)
            upper = need_int(o.get('upper'), -1000000, 1000000)
            if lower > upper:
                raise Invalid()
            dom = o['domain']
            if dom is not None and (not is_name(dom) or dom not in domain_set):
                raise Invalid()
            observations.append({'id': oid, 'metric': metric, 'target': target,
                                 'lower': lower, 'upper': upper, 'domain': dom})
        snapshots.append({'id': sid, 'bounds': bounds, 'controller': controller,
                          'tolerance': tolerance, 'observations': observations})

    return {'id': rid, 'nodes': nodes, 'edges': edges,
            'commodities': commodities, 'domains': domains,
            'max_faults': max_faults, 'snapshots': snapshots}


# --------------------------------------------------------------------------
# Model construction
# --------------------------------------------------------------------------

class Model(object):
    """Scaled integer coefficients of one incident request."""

    def __init__(self, inst):
        self.inst = inst
        nodes = inst['nodes']
        edges = inst['edges']
        coms = inst['commodities']
        snaps = inst['snapshots']
        self.E = len(edges)
        self.C = len(coms)
        self.S = len(snaps)
        edge_index = {e['id']: i for i, e in enumerate(edges)}
        com_index = {c['id']: i for i, c in enumerate(coms)}
        node_index = {n: i for i, n in enumerate(nodes)}

        K = 1
        for c in coms:
            K = lcm(K, sum(r['weight'] for r in c['routes']))
        self.K = K

        # n[ci][ei]: scaled load contribution of commodity ci on edge ei.
        n = [[0] * self.E for _ in range(self.C)]
        for ci, c in enumerate(coms):
            W = sum(r['weight'] for r in c['routes'])
            sc = K // W
            for r in c['routes']:
                w = r['weight'] * sc
                for eid in r['edges']:
                    n[ci][edge_index[eid]] += w
        self.n = n

        self.link_coef = [tuple(n[ci][ei] for ci in range(self.C))
                          for ei in range(self.E)]
        self.dem_coef = [tuple(K if ci == j else 0 for ci in range(self.C))
                         for j in range(self.C)]
        self.ing_coef = [tuple(K if coms[ci]['source'] == v else 0
                               for ci in range(self.C)) for v in nodes]
        self.egr_coef = [tuple(K if coms[ci]['target'] == v else 0
                               for ci in range(self.C)) for v in nodes]

        def coef_of(metric, target):
            if metric == 'demand':
                return self.dem_coef[com_index[target]]
            if metric == 'link':
                return self.link_coef[edge_index[target]]
            if metric == 'ingress':
                return self.ing_coef[node_index[target]]
            return self.egr_coef[node_index[target]]

        domains = inst['domains']
        self.dom_obs = {d: [] for d in domains}
        self.trusted = []
        for si, sp in enumerate(snaps):
            for o in sp['observations']:
                coef = coef_of(o['metric'], o['target'])
                lo = o['lower'] * K
                hi = o['upper'] * K
                if o['domain'] is None:
                    self.trusted.append((si, coef, lo, hi))
                else:
                    self.dom_obs[o['domain']].append((si, coef, lo, hi))
        # Domains without observations can never be faulty.
        self.observed_domains = [d for d in domains if self.dom_obs[d]]

    def static_bounds(self, s, coef):
        """Extremes of sum(coef*q[s]) over the demand box alone."""
        lo = hi = 0
        bnd = self.inst['snapshots'][s]['bounds']
        for c in range(self.C):
            cf = coef[c]
            if cf == 0:
                continue
            blo, bhi = bnd[c]
            if cf > 0:
                lo += cf * blo
                hi += cf * bhi
            else:
                lo += cf * bhi
                hi += cf * blo
        return lo, hi


class VarSet(object):
    """One Z3 encoding of a model, over Int or Real demand variables."""

    def __init__(self, mdl, real, tag):
        self.mdl = mdl
        self.real = real
        C, S = mdl.C, mdl.S
        mk = z3.Real if real else z3.Int
        zero = z3.RealVal(0) if real else z3.IntVal(0)
        self.zero = zero
        q = [[mk('%s_q_%d_%d' % (tag, s, c)) for c in range(C)] for s in range(S)]
        self.q = q
        inst = mdl.inst
        base = []
        for s in range(S):
            bnd = inst['snapshots'][s]['bounds']
            for c in range(C):
                lo, hi = bnd[c]
                base.append(q[s][c] >= lo)
                base.append(q[s][c] <= hi)
        K = mdl.K
        for s in range(S):
            for ei in range(mdl.E):
                coef = mdl.link_coef[ei]
                terms = [coef[c] * q[s][c] for c in range(C) if coef[c]]
                if not terms:
                    continue
                base.append(z3.Sum(terms) <= inst['edges'][ei]['capacity'] * K)
        self._exprs = {}
        for (si, coef, lo, hi) in mdl.trusted:
            e = self.expr(si, coef)
            base.append(e >= lo)
            base.append(e <= hi)
        self.fvars = {}
        for i, d in enumerate(mdl.observed_domains):
            fb = z3.Bool('%s_f_%d' % (tag, i))
            self.fvars[d] = fb
            conj = []
            for (si, coef, lo, hi) in mdl.dom_obs[d]:
                e = self.expr(si, coef)
                conj.append(e >= lo)
                conj.append(e <= hi)
            base.append(z3.Implies(z3.Not(fb), z3.And(conj) if conj else
                                   z3.BoolVal(True)))
        self.fvar_list = [self.fvars[d] for d in mdl.observed_domains]
        self.base = base

    def expr(self, s, coef):
        key = (s, coef)
        e = self._exprs.get(key)
        if e is None:
            terms = [coef[c] * self.q[s][c] for c in range(self.mdl.C)
                     if coef[c]]
            e = z3.Sum(terms) if terms else self.zero
            self._exprs[key] = e
        return e


# --------------------------------------------------------------------------
# Inference engine
# --------------------------------------------------------------------------

_DBG = bool(os.environ.get('ANALYZE_DEBUG'))
_T0 = time.time()
_PHASE = [0.0]


def _tick(label):
    if not _DBG:
        return
    t = time.time()
    sys.stderr.write('[%7.3f] %s (+%.3f)\n' % (t - _T0, label, t - _PHASE[0]))
    sys.stderr.flush()
    _PHASE[0] = t


def rat_of(v):
    """Z3 numeral -> Fraction, or None."""
    try:
        if z3.is_int_value(v):
            return Fraction(v.as_long())
        if z3.is_rat_value(v) or z3.is_real_value(v):
            return v.as_fraction()
    except Exception:
        return None
    return None


def floor_frac(f):
    return f.numerator // f.denominator


def ceil_frac(f):
    return -((-f.numerator) // f.denominator)


def rat_str(scaled, K):
    """Exact reduced 'num/den' string of the rational value scaled/K."""
    f = Fraction(scaled, K)
    return '%d/%d' % (f.numerator, f.denominator)


class Engine(object):
    def __init__(self, inst):
        self.inst = inst
        self.mdl = Model(inst)
        mdl = self.mdl
        self.iv = VarSet(mdl, False, 'i')
        self.rv = VarSet(mdl, True, 'r')
        self.sol = z3.Solver()
        self.sol.add(self.iv.base)
        self.ropt = z3.Optimize()
        self.ropt.add(self.rv.base)
        self.k = None
        self.lpcache = {}
        self.intcache = {}
        self.nchecks = 0

    # -- small helpers ---------------------------------------------------
    def check(self, extra, real=False):
        """SAT/UNSAT of base plus extra (list of constraints)."""
        obj = self.ropt if real else self.sol
        obj.push()
        for e in extra:
            obj.add(e)
        r = obj.check()
        obj.pop()
        if r == z3.unknown:
            raise EngineError('z3 returned unknown')
        return r == z3.sat

    def find_k(self):
        fvars = self.iv.fvar_list
        maxf = self.inst['max_faults']
        k = None
        for m in range(maxf + 1):
            extra = [z3.AtMost(*(fvars + [m]))] if fvars else []
            self.sol.push()
            for e in extra:
                self.sol.add(e)
            r = self.sol.check()
            self.sol.pop()
            if r == z3.unknown:
                raise EngineError('z3 unknown while searching k')
            if r == z3.sat:
                k = m
                break
        if k is None:
            return None
        if fvars:
            rf = self.rv.fvar_list
            self.sol.add(z3.AtMost(*(fvars + [k])))
            self.sol.add(z3.AtLeast(*(fvars + [k])))
            self.ropt.add(z3.AtMost(*(rf + [k])))
            self.ropt.add(z3.AtLeast(*(rf + [k])))
        self.k = k
        return k

    def tighten(self, s, coef, lo, hi):
        """Assert implied objective bounds in both encodings."""
        ei = self.iv.expr(s, coef)
        er = self.rv.expr(s, coef)
        self.sol.add(ei >= lo)
        self.sol.add(ei <= hi)
        self.ropt.add(er >= lo)
        self.ropt.add(er <= hi)

    def lp_pair(self, s, coef):
        key = (s, coef)
        if key in self.lpcache:
            return self.lpcache[key]
        e = self.rv.expr(s, coef)
        res = [None, None]
        for idx in (0, 1):
            self.ropt.push()
            h = self.ropt.minimize(e) if idx == 0 else self.ropt.maximize(e)
            r = self.ropt.check()
            if r == z3.sat:
                res[idx] = rat_of(self.ropt.lower(h) if idx == 0
                                  else self.ropt.upper(h))
            self.ropt.pop()
        out = (res[0], res[1])
        self.lpcache[key] = out
        return out

    def refine(self, s, coef, lo, hi, maximize):
        """Exact integer extremum inside [lo, hi] (inclusive)."""
        e = self.iv.expr(s, coef)
        if maximize:
            if lo == hi or self.check([e >= hi]):
                return hi
            a, b = lo, hi - 1
            while a < b:
                mid = (a + b + 1) // 2
                if self.check([e >= mid]):
                    a = mid
                else:
                    b = mid - 1
            return a
        else:
            if lo == hi or self.check([e <= lo]):
                return lo
            a, b = lo + 1, hi
            while a < b:
                mid = (a + b) // 2
                if self.check([e <= mid]):
                    b = mid
                else:
                    a = mid + 1
            return a

    def int_pair(self, s, coef):
        """Exact (min, max) of sum(coef*q[s]) over F."""
        key = (s, coef)
        hit = self.intcache.get(key)
        if hit is not None:
            return hit
        slo, shi = self.mdl.static_bounds(s, coef)
        if slo == shi:
            self.intcache[key] = (slo, slo)
            return (slo, slo)
        lmin, lmax = self.lp_pair(s, coef)
        if lmin is None or lmax is None:
            a, b = slo, shi
        else:
            a = max(slo, ceil_frac(lmin))
            b = min(shi, floor_frac(lmax))
            if a > b:
                a, b = slo, shi
        lo = self.refine(s, coef, a, b, False)
        hi = self.refine(s, coef, a, b, True)
        self.intcache[key] = (lo, hi)
        return (lo, hi)

    # -- results ---------------------------------------------------------
    def witness_from_model(self, m):
        mdl = self.mdl
        C, S = mdl.C, mdl.S
        q = [[m.evaluate(mdl_ := self.iv.q[s][c], model_completion=True)
              for c in range(C)] for s in range(S)]
        vals = []
        for s in range(S):
            row = []
            for c in range(C):
                v = q[s][c]
                if z3.is_int_value(v):
                    row.append(v.as_long())
                else:
                    f = rat_of(v)
                    if f is None or f.denominator != 1:
                        raise EngineError('non integer demand in model')
                    row.append(int(f))
            vals.append(row)
        return vals

    def evaluate(self, q):
        """Scaled link loads and the actually violated domain set."""
        mdl = self.mdl
        links = []
        for s in range(mdl.S):
            row = []
            for ei in range(mdl.E):
                coef = mdl.link_coef[ei]
                row.append(sum(cf * q[s][c] for c, cf in enumerate(coef) if cf))
            links.append(row)
        faults = []
        for d in mdl.observed_domains:
            for (si, coef, lo, hi) in mdl.dom_obs[d]:
                v = sum(cf * q[si][c] for c, cf in enumerate(coef) if cf)
                if v < lo or v > hi:
                    faults.append(d)
                    break
        return links, faults


def solve(inst):
    rid = inst['id']
    _tick('start')
    eng = Engine(inst)
    mdl = eng.mdl
    C, S, E, K = mdl.C, mdl.S, mdl.E, mdl.K
    snaps = inst['snapshots']
    _tick('model built C=%d S=%d E=%d trusted=%d domobs=%d' %
          (C, S, E, len(mdl.trusted), len(mdl.observed_domains)))

    k = eng.find_k()
    _tick('k=%s' % k)
    if k is None:
        return {'id': rid, 'status': 'infeasible'}

    # A first feasible explanation (also seeds nothing else).
    if eng.sol.check() != z3.sat:
        raise EngineError('model unsat after fixing k')
    wq = eng.witness_from_model(eng.sol.model())
    _tick('witness')

    # ---- demand ranges (then propagate them into both encodings) --------
    dem_ranges = []
    ambiguous = False
    for s in range(S):
        row = []
        for c in range(C):
            blo, bhi = snaps[s]['bounds'][c]
            if blo == bhi:
                row.append([blo, bhi])
                continue
            lo, hi = eng.int_pair(s, mdl.dem_coef[c])
            lo //= K
            hi //= K
            row.append([lo, hi])
            if lo != hi:
                ambiguous = True
            eng.tighten(s, mdl.dem_coef[c], lo * K, hi * K)
        dem_ranges.append(row)
    _tick('demand ranges done (%d lp, %d int)' % (len(eng.lpcache),
                                                 len(eng.intcache)))

    # ---- link ranges ----------------------------------------------------
    link_ranges = []
    for s in range(S):
        lrow = []
        for ei in range(E):
            coef = mdl.link_coef[ei]
            lo, hi = eng.int_pair(s, coef)
            lrow.append([rat_str(lo, K), rat_str(hi, K)])
        link_ranges.append(lrow)
    _tick('link ranges done (%d lp, %d int, %d checks)' %
          (len(eng.lpcache), len(eng.intcache), eng.nchecks))

    wlinks, wfaults = eng.evaluate(wq)
    if len(wfaults) != k:
        raise EngineError('witness has %d faults, expected %d' % (len(wfaults), k))
    status = 'ambiguous' if ambiguous else 'unique'

    # ---- forced / possible faulty domains -------------------------------
    forced = []
    possible = []
    for d in mdl.observed_domains:
        fb = eng.iv.fvars[d]
        if not eng.check([z3.Not(fb)]):
            forced.append(d)
            possible.append(d)
        elif eng.check([fb]):
            possible.append(d)
    _tick('faults done')

    # ---- controller verdicts --------------------------------------------
    verdicts = []
    for s in range(S):
        ctrl = snaps[s]['controller']
        tol = snaps[s]['tolerance']
        agree = []
        for c in range(C):
            agree.append(eng.iv.q[s][c] >= ctrl[c] - tol)
            agree.append(eng.iv.q[s][c] <= ctrl[c] + tol)
        a = z3.And(agree) if agree else z3.BoolVal(True)
        yes = eng.check([a])
        no = eng.check([z3.Not(a)])
        if yes and no:
            verdicts.append('undetermined')
        elif yes:
            verdicts.append('consistent')
        else:
            verdicts.append('inconsistent')
    _tick('verdicts done')

    # ---- alternative explanation ----------------------------------------
    alt = None
    if ambiguous:
        for s in range(S):
            if alt is not None:
                break
            for c in range(C):
                lo, hi = dem_ranges[s][c]
                if lo == hi:
                    continue
                v = wq[s][c]
                extra = (eng.iv.q[s][c] >= v + 1) if v < hi else \
                        (eng.iv.q[s][c] <= v - 1)
                if eng.check([extra]):
                    aq = eng.witness_from_model(eng.sol.model())
                    alinks, afaults = eng.evaluate(aq)
                    if len(afaults) != k:
                        raise EngineError('alternative fault count mismatch')
                    alt = {'demands': aq,
                           'links': [[rat_str(v2, K) for v2 in row]
                                     for row in alinks],
                           'faults': afaults}
                break
    _tick('alternative done')

    snap_out = [{'id': snaps[s]['id'], 'demands': dem_ranges[s],
                 'links': link_ranges[s], 'verdict': verdicts[s]}
                for s in range(S)]

    return {'id': rid, 'status': status, 'min_faults': k,
            'faults': {'forced': forced, 'possible': possible},
            'snapshots': snap_out,
            'witness': {'demands': wq,
                        'links': [[rat_str(v, K) for v in row] for row in wlinks],
                        'faults': wfaults},
            'alternative': alt}


# --------------------------------------------------------------------------
# Driver
# --------------------------------------------------------------------------

def process_line(raw):
    try:
        value = json.loads(raw, parse_constant=_bad_const)
    except Exception:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    rid = None
    if isinstance(value, dict):
        cand = value.get('id')
        if is_name(cand):
            rid = cand
    try:
        inst = parse_request(value)
    except Invalid:
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    except RecursionError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
    try:
        return solve(inst)
    except Exception:
        traceback.print_exc()
        return {'id': rid, 'status': 'error', 'error': 'invalid_instance'}


def main():
    data = sys.stdin.buffer.read()
    if not data:
        return
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    out = sys.stdout
    for raw in lines:
        out.write(json.dumps(process_line(raw), separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
